// Embeds shared/sqlite-schema/migrations/*.sql into
// lib/core/database/sqlite_migrations.g.dart, because the Flutter app cannot
// read files outside its package at runtime.
//
// Run from mobile/ after changing the shared migrations:
//   dart run tool/sync_sqlite_schema.dart
// test/core/database/sqlite_migrations_sync_test.dart fails while the
// generated file is out of date.
import 'dart:io';

const migrationsDir = '../shared/sqlite-schema/migrations';
const outputFile = 'lib/core/database/sqlite_migrations.g.dart';

final _fileName = RegExp(r'^v(\d+)_.*\.sql$');

/// Builds the Dart source for the migrations in [dir] (relative to mobile/).
String buildMigrationsSource({String dir = migrationsDir}) {
  final files = Directory(dir)
      .listSync()
      .whereType<File>()
      .map((f) => f.uri.pathSegments.last)
      .where(_fileName.hasMatch)
      .toList()
    ..sort();
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/sync_sqlite_schema.dart from shared/sqlite-schema/migrations. Do not edit.')
    ..writeln('// Run `dart run tool/sync_sqlite_schema.dart` in mobile/ after changing the shared SQL.')
    ..writeln()
    ..writeln("import 'sqlite_migration.dart';")
    ..writeln()
    ..writeln('const sqliteMigrations = <SqliteMigration>[');
  for (final file in files) {
    final version = int.parse(_fileName.firstMatch(file)!.group(1)!);
    final sql = File('$dir/$file').readAsStringSync().replaceAll('\r\n', '\n');
    out
      ..writeln('  SqliteMigration(')
      ..writeln('    version: $version,')
      ..writeln("    name: '${file.substring(0, file.length - 4)}',")
      ..writeln("    sql: '''${_escape(sql)}''',")
      ..writeln('  ),');
  }
  out.writeln('];');
  return out.toString();
}

/// Escapes [text] for a non-raw `'''` Dart string literal.
String _escape(String text) {
  var s = text.replaceAll(r'\', r'\\').replaceAll(r'$', r'\$');
  while (s.contains("'''")) {
    s = s.replaceAll("'''", "''\\'");
  }
  if (s.endsWith("'")) s = '${s.substring(0, s.length - 1)}\\\'';
  return s;
}

void main() {
  File(outputFile).writeAsStringSync(buildMigrationsSource());
  stdout.writeln('wrote $outputFile');
}
